+    let j = i.min(SHRUNKEN_PZ_NSTEPS - 1);
+    (SHRUNKEN_PZ_A[j] as usize, SHRUNKEN_PZ_B[j] as usize, SHRUNKEN_PZ_CA[j] as usize,
+     SHRUNKEN_PZ_CB[j] as usize, SHRUNKEN_PZ_Q[j] as usize)
+}
